<?php require 'config.php'; require_admin(); $msg=''; if(isset($_POST['add'])){$code=trim($_POST['subject_code']);$name=trim($_POST['subject_name']);$max=(int)$_POST['max_marks'];$pass=(int)$_POST['pass_marks'];$s=$conn->prepare('INSERT INTO subjects (subject_code,subject_name,max_marks,pass_marks) VALUES (?,?,?,?)');$s->bind_param('ssii',$code,$name,$max,$pass);$msg=$s->execute()?'Subject added successfully.':'Could not add subject. Code may already exist.';} if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM subjects WHERE id=$id");header('Location: subjects.php');exit;} $subjects=$conn->query('SELECT * FROM subjects ORDER BY id DESC');$page_title='Manage Subjects'; require 'header.php'; ?>
<div class="page-head"><h1>Subjects</h1><p>Configure subjects and passing marks.</p></div><div class="two-col"><form class="panel" method="post"><h2>Add Subject</h2><?php if($msg):?><p class="alert"><?=e($msg)?></p><?php endif;?><label>Subject Code</label><input name="subject_code" required><label>Subject Name</label><input name="subject_name" required><label>Maximum Marks</label><input type="number" name="max_marks" value="100" min="1" required><label>Pass Marks</label><input type="number" name="pass_marks" value="35" min="0" required><button name="add">Add Subject</button></form><div class="panel table-wrap"><h2>All Subjects</h2><table><tr><th>Code</th><th>Subject</th><th>Max</th><th>Pass</th><th></th></tr><?php while($s=$subjects->fetch_assoc()):?><tr><td><?=e($s['subject_code'])?></td><td><?=e($s['subject_name'])?></td><td><?=$s['max_marks']?></td><td><?=$s['pass_marks']?></td><td><a class="danger" onclick="return confirm('Delete this subject?')" href="?delete=<?=$s['id']?>">Delete</a></td></tr><?php endwhile;?></table></div></div>
<?php require 'footer.php'; ?>
